function present(index=0){let frames=board.objects.filter(s=>s.type==='frame').sort((a,b)=>a.x-b.x);if(!frames.length){toast('Add a frame to start presenting.');return}frameIndex=(index+frames.length)%frames.length;document.body.classList.add('presenting');$('presentation').hidden=false;let r=$('canvas').getBoundingClientRect(),f=frames[frameIndex],padding=60;zoom=Math.min((r.width-padding*2)/f.w,(r.height-150)/f.h);pan={x:r.width/2-(f.x+f.w/2)*zoom,y:(r.height-75)/2-(f.y+f.h/2)*zoom};render();$('presentLabel').textContent=`${frameIndex+1} / ${frames.length}   ${f.text||'Untitled frame'}`}
