// Precision drawing keeps wall width independent from stroke weight.
function isSegment(s){return !!s&&['wall','line','arrow','dimension','connector'].includes(s.type)&&Number.isFinite(s.x2)&&Number.isFinite(s.y2)}
function drawingAnchors(excludeId){return G.anchors(board.objects.filter(s=>visible(s)&&s.layer==='drawing'&&s.id!==excludeId))}
function snappedStart(p){const anchor=options.endpointSnap?G.nearestAnchor(p,drawingAnchors(),Math.min(35,10/zoom)):null;return anchor?{x:anchor.x,y:anchor.y}:G.snap(p,options.snap,settings.grid)}
function precisePoint(a,b,shift=false,excludeId,editingEndpoint=false){const unitsToPixels=settings.pixels/settings.real;return G.preciseEndpoint(a,b,{...options,shift,gridStep:settings.grid,exactAngle:editingEndpoint?'':options.exactAngle,exactLength:editingEndpoint||options.exactLength===''?'':+options.exactLength*unitsToPixels},drawingAnchors(excludeId),Math.min(35,10/zoom))}
function hideMeasurements(){if($('drawingReadout'))$('drawingReadout').hidden=true}
function cancelDraft(){gesture=null;$('draftObjects').replaceChildren();hideMeasurements()}
function showMeasurements(s,kind){if(!isSegment(s)){hideMeasurements();return}const length=G.distance(s,{x:s.x2,y:s.y2})*settings.real/settings.pixels,angle=G.segmentAngle(s,{x:s.x2,y:s.y2});let readout=$('drawingReadout');readout.hidden=false;readout.innerHTML=`<b>${length.toFixed(3)} <small>${settings.units}</small></b><span>${angle.toFixed(1)}°</span>${kind==='endpoint'?'<em>● Endpoint</em>':kind==='exact'?'<em>↳ Exact</em>':''}`;readout.style.left=Math.max(78,Math.min(window.innerWidth-210,s.x2*zoom+pan.x+15))+'px';readout.style.top=Math.max(140,Math.min(window.innerHeight-145,s.y2*zoom+pan.y-45))+'px'}
function showDraft(s){let g=$('draftObjects');g.replaceChildren(drawNode(s));if(isSegment(s)){g.append(el('circle',{cx:s.x,cy:s.y,r:3/zoom,fill:'#8171d9','pointer-events':'none'}));g.append(el('circle',{cx:s.x2,cy:s.y2,r:5/zoom,fill:'#fff',stroke:s._snapKind==='endpoint'?'#328c72':'#8171d9','stroke-width':1.5/zoom,'pointer-events':'none'}));if(s.type==='wall'&&s.wallStyle==='double')g.append(el('line',{x1:s.x,y1:s.y,x2:s.x2,y2:s.y2,stroke:'#8d80ba','stroke-width':.7/zoom,'stroke-dasharray':`${4/zoom} ${4/zoom}`,'pointer-events':'none'}));showMeasurements(s,s._snapKind)}}
function commitSegment(s){hideMeasurements();$('draftObjects').replaceChildren();const b=G.bounds(s);if(b.w+b.h<=(isSegment(s)?1e-6:3/zoom))return false;if(s.type==='sketch'&&s.points.length<2)return false;checkpoint();delete s._snapKind;board.objects.push(s);selected=new Set([s.id]);if(!['wall','line','sketch','arrow','dimension'].includes(tool))setTool('select');render();renderOutline();if(panelTab==='properties')renderStudio();saveSoon();return true}
function wallControlsHTML(context,wall=options,disabled=false){const style=wall.wallStyle||'single',thickness=wall.wallThickness||6;return `<div class="wall-setting"><label class="field-label">Wall style</label><div class="segmented"><button data-wall-context="${context}" data-wall-style="single" class="${style==='single'?'active':''}" ${disabled?'disabled':''}><svg viewBox="0 0 32 18" aria-hidden="true"><path d="M3 9h26"/></svg>Single line</button><button data-wall-context="${context}" data-wall-style="double" class="${style==='double'?'active':''}" ${disabled?'disabled':''}><svg viewBox="0 0 32 18" aria-hidden="true"><path d="M3 6h26M3 12h26"/></svg>Double line</button></div><label class="field-label">Wall thickness <span class="view-only">Physical width</span></label><div class="wall-presets">${[[4,'Thin'],[6,'Medium'],[8,'Thick']].map(([n,label])=>`<button data-wall-context="${context}" data-wall-thickness="${n}" class="${thickness===n?'active':''}" ${disabled?'disabled':''}><svg viewBox="0 0 48 26" aria-hidden="true"><path d="M4 ${13-n/2}h40M4 ${13+n/2}h40"/></svg><b>${label}</b><small>${n}″</small></button>`).join('')}</div><p class="panel-help">4″ / 6″ / 8″ (${[4,6,8].map(n=>Math.round(n*25.4)).join(' / ')} mm). Width uses your calibrated drawing scale; the outline stays thin.</p></div>`}
function renderDrawingSettings(){const angle=options.straight?options.angleStep:0;$('studioContent').innerHTML=`<div class="panel-section"><div class="eyebrow">PRECISE DRAWING <span class="tag">${escapeHTML(tool==='wall'?'WALL TOOL':'LINE CONTROLS')}</span></div><div class="drawing-tool-pick"><button data-precision-tool="wall" class="${tool==='wall'?'active':''}">${icon('wall')} Wall</button><button data-precision-tool="line" class="${tool==='line'?'active':''}">${icon('line')} Line</button></div><label class="field-label">Input method</label><div class="segmented"><button data-input-mode="drag" class="${options.inputMode==='drag'?'active':''}">Click & drag</button><button data-input-mode="click" class="${options.inputMode==='click'?'active':''}">Click two points</button></div><label class="check-row">Continue connected walls<input id="chainWalls" class="switch" type="checkbox" ${options.chain?'checked':''}></label><p class="panel-help">With two-point input, click each corner to continue a wall. Escape finishes the run.</p></div>
 <div class="panel-section"><div class="eyebrow">SNAPPING & CONSTRAINTS</div><label class="check-row">Snap to existing endpoints<input id="endpointSnap" class="switch" type="checkbox" ${options.endpointSnap?'checked':''}></label><label class="check-row">Snap to grid<input id="drawingGridSnap" class="switch" type="checkbox" ${options.snap?'checked':''}></label><div class="precision-grid"><label>Grid step · px<input id="drawingGridStep" type="number" min="1" max="100" value="${settings.grid}"></label><label>Angle snap<select id="angleSnap"><option value="0" ${angle===0?'selected':''}>Free angle</option>${[90,45,15].map(n=>`<option value="${n}" ${angle===n?'selected':''}>${n}° increments</option>`).join('')}</select></label></div><div class="precision-grid" style="margin-top:14px"><label>Exact length · ${settings.units}<input id="exactLength" type="number" min="0.001" step="0.001" placeholder="Cursor" value="${escapeHTML(options.exactLength)}"></label><label>Exact angle · °<input id="exactAngle" type="number" step="0.1" placeholder="Cursor" value="${escapeHTML(options.exactAngle)}"></label></div><div class="precision-note">0° → right · 90° ↑ up</div><button class="small-button" id="clearConstraints">Clear exact constraints</button><p class="panel-help">Blank fields follow your cursor. Exact values override grid and endpoint snapping. Hold Shift for a 90° lock.</p></div>
 <div class="panel-section"><div class="eyebrow">WALL CONSTRUCTION</div>${wallControlsHTML('draw')}</div>
 <div class="panel-section"><div class="eyebrow">THIN LINEWEIGHTS <span class="tag">${options.width} PX</span></div><label class="field-label">Drawing print scale</label><select id="paperScale" class="layer-select">${[[.0625,'1/16″ = 1′'],[.125,'1/8″ = 1′'],[.25,'1/4″ = 1′'],[.5,'1/2″ = 1′'],[1,'1″ = 1′']].map(([n,label])=>`<option value="${n}" ${+settings.paperScale===n?'selected':''}>${label}</option>`).join('')}</select><label class="check-row">Scale-aware lineweights<input id="autoLineweight" class="switch" type="checkbox" ${settings.autoLineweight?'checked':''}></label><div class="stroke-presets">${[1,1.5,2].map(n=>`<button data-stroke-weight="${n}" class="${options.width===n?'active':''}"><svg viewBox="0 0 40 12" aria-hidden="true"><path d="M3 6h34" stroke-width="${n}"/></svg>${n} px</button>`).join('')}</div><button class="outline-button" data-action="thin-lines" style="margin-top:13px">Apply thin weights to drawing</button><p class="panel-help">½″ = 1′ uses 2 px. Stroke values are at 100% zoom. Calibrate pixels to a known distance in Trace for accurate lengths and wall widths; print scale alone cannot calibrate an image.</p></div>`;
 document.querySelectorAll('[data-precision-tool]').forEach(n=>n.onclick=()=>{setTool(n.dataset.precisionTool);showPanel('draw')});
 document.querySelectorAll('[data-input-mode]').forEach(n=>n.onclick=()=>{cancelDraft();options.inputMode=n.dataset.inputMode;renderDrawingSettings();saveSoon()});
 [['chainWalls','chain'],['endpointSnap','endpointSnap'],['drawingGridSnap','snap']].forEach(([id,key])=>$(id).onchange=e=>{options[key]=e.target.checked;renderToolOptions();saveSoon()});
 $('drawingGridStep').onchange=e=>{settings.grid=Math.min(100,Math.max(1,+e.target.value||10));e.target.value=settings.grid;saveSoon()};
 $('angleSnap').onchange=e=>{options.angleStep=+e.target.value;options.straight=options.angleStep!==0;renderToolOptions();saveSoon()};
 ['exactLength','exactAngle'].forEach(id=>$(id).onchange=e=>{const value=e.target.value;options[id]=value!==''&&Number.isFinite(+value)&&(id!=='exactLength'||+value>0)?+value:'';e.target.value=options[id]});
 $('clearConstraints').onclick=()=>{options.exactLength='';options.exactAngle='';renderDrawingSettings()};
 $('paperScale').onchange=e=>{settings.paperScale=+e.target.value;if(settings.autoLineweight)options.width=G.lineweightForScale(settings.paperScale);renderDrawingSettings();renderToolOptions();saveSoon()};
 $('autoLineweight').onchange=e=>{settings.autoLineweight=e.target.checked;if(settings.autoLineweight)options.width=G.lineweightForScale(settings.paperScale);renderDrawingSettings();renderToolOptions();saveSoon()};
 document.querySelectorAll('[data-stroke-weight]').forEach(n=>n.onclick=()=>{options.width=+n.dataset.strokeWeight;settings.autoLineweight=false;renderDrawingSettings();renderToolOptions();saveSoon()});bindWallControls($('studioContent'));
}
function bindWallControls(root,selectedWall){root.querySelectorAll('[data-wall-style],[data-wall-thickness]').forEach(n=>n.onclick=()=>{const props=n.dataset.wallStyle?{wallStyle:n.dataset.wallStyle}:{wallThickness:+n.dataset.wallThickness};if(selectedWall){updateSelected(props)}else{Object.assign(options,props);renderDrawingSettings();saveSoon()}})}
function segmentPropertiesHTML(s,locked){const length=G.distance(s,{x:s.x2,y:s.y2})*settings.real/settings.pixels,angle=G.segmentAngle(s,{x:s.x2,y:s.y2});return `<div class="panel-section"><div class="eyebrow">SEGMENT GEOMETRY</div><div class="precision-grid"><label>Length · ${settings.units}<input id="segmentLength" type="number" min="0.001" step="0.001" value="${length.toFixed(3)}" ${locked?'disabled':''}></label><label>Angle · °<input id="segmentAngle" type="number" step="0.1" value="${angle.toFixed(2)}" ${locked?'disabled':''}></label></div><div class="precision-grid coordinates">${[['x','Start X'],['y','Start Y'],['x2','End X'],['y2','End Y']].map(([key,label])=>`<label>${label} · px<input data-endpoint-coordinate="${key}" type="number" step="0.1" value="${s[key].toFixed(2)}" ${locked?'disabled':''}></label>`).join('')}</div><p class="panel-help">Drag either round endpoint handle to reshape this segment. Shift locks the angle.</p>${s.type==='wall'?wallControlsHTML('object',s,locked):''}</div>`}
function bindSegmentProperties(s,locked){if(!isSegment(s)||locked)return;const apply=()=>{const length=+$('segmentLength').value,angle=+$('segmentAngle').value;if(!(length>0)||!Number.isFinite(angle))return;const p=G.fromPolar(s,length*settings.pixels/settings.real,angle);updateSelected({x2:p.x,y2:p.y})};$('segmentLength').onchange=apply;$('segmentAngle').onchange=apply;document.querySelectorAll('[data-endpoint-coordinate]').forEach(n=>n.onchange=()=>{if(Number.isFinite(+n.value))updateSelected({[n.dataset.endpointCoordinate]:+n.value})});bindWallControls($('studioContent'),s)}
function applyThinWeights(){const weight=settings.autoLineweight?G.lineweightForScale(settings.paperScale):options.width;const lines=board.objects.filter(s=>editable(s)&&s.layer==='drawing'&&(['wall','line','sketch','arrow','connector','door','window','dimension'].includes(s.type)||(s.type==='room'&&!s.noOutline)));if(!lines.length){toast('Draw a line or wall first.');return}checkpoint();lines.forEach(s=>s.width=s.type==='dimension'?Math.min(1,weight):weight);options.width=weight;render();renderStudio();renderToolOptions();saveSoon();toast(`Applied ${weight} px strokes to ${lines.length} drawing objects. Undo is available.`)}
